// CloudIT - Vercel Traffic Collector — Load Config.
// Purpose: compute the shared run constants and hold the plain (NON-SECRET)
// Vercel project identifiers. All timestamps are computed at RUN TIME —
// never hardcode a test clock: publishedAt must be within ±5 minutes of
// ingestion (0004 stale_timestamp).
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// The reporting window is YESTERDAY'S complete UTC day [periodStart,
// periodEnd) and the idempotency bucket is 'vercel-traffic-' + that day
// (opaque; only uniqueness matters). freshUntil is observedAt + 48h, the
// seeded daily-traffic freshness. teamId/projectId are NOT secrets — the
// owner replaces the placeholders in this node before activation.

const now = new Date();
const nowMs = now.getTime();
const DAY_MS = 24 * 60 * 60 * 1000;
const pad = (n) => String(n).padStart(2, '0');
const ymd = (d) => d.getUTCFullYear() + '-' + pad(d.getUTCMonth() + 1) + '-' + pad(d.getUTCDate());
const since = ymd(new Date(nowMs - DAY_MS));   // yesterday 00:00 UTC
const until = ymd(new Date(nowMs));            // today 00:00 UTC (exclusive)

return [{
  json: {
    teamId: 'team_REPLACE_ME',
    projectId: 'project_REPLACE_ME',
    since,
    until,
    periodStart: since + 'T00:00:00.000Z',
    periodEnd: until + 'T00:00:00.000Z',
    observedAt: now.toISOString(),
    publishedAt: now.toISOString(),
    freshUntil: new Date(nowMs + 48 * 3600 * 1000).toISOString(),
    bucket: 'vercel-traffic-' + since
  }
}];

// CloudIT - Vercel Traffic Collector — Normalize Traffic.
// Purpose: turn the two Web Analytics responses into ONE traffic_summary
// record plus the provider_connection record — or, when either call failed,
// into the single failure provider_connection.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).

// - A top-route path that fails the ingest safety regex
//   (^/[a-z0-9/._~-]{0,200}$ plus the /admin /agent /share /api /_next
//   /_vercel prefixes and /others) is SKIPPED — one bad path can never kill
//   the batch. topRoutes is capped at 20 (ingest limit).
// - visitors AND pageviews both absent -> coverage 'no_data', both omitted.
// - On failure: ONE provider_connection {reachable:false,
//   authorizationState denied on 401/403 else unknown, failureCategory from
//   the closed allowlist}; lastSuccessfulAt is omitted.
//
// WIRING NOTE: this node reads the Get Daily Visits output via
// $('Get Daily Visits').first().json — safe because the chain is a single
// straight line executed exactly once (the proven Phase 6 v2 pattern: n8n
// HTTP nodes do not pass input fields through, so the first response cannot
// ride the chain downstream). VERIFY-ON-FIRST-RUN: confirm the live row
// shape of both aggregate responses (documented {timestamp, pageviews,
// visitors} for by=day; requestPath + pageviews per row for by=requestPath);
// a wrong field name simply omits that value — it cannot poison the batch.

const config = $('Load Config').first().json;
const daily = $('Get Daily Visits').first().json;
const paths = $input.first().json;

// --- failure inspection -----------------------------------------------------
// A failed HTTP node (onError: continueRegularOutput) yields an item whose
// json is an error object; a 200 whose body is a provider error document
// carries an error field too. Anything that is not a confirmed healthy body
// counts as a failure; the status code is best-effort (network/timeout
// failures carry none -> category provider_unavailable, state unknown).
function failureOf(item) {
  if (!item || typeof item !== 'object' || Array.isArray(item)) {
    return { failed: true, status: null, timedOut: false };
  }
  const err = item.error
    ? (typeof item.error === 'object' ? item.error : { message: String(item.error) })
    : null;
  if (err === null) return { failed: false, status: null, timedOut: false };
  const msg = String(err.message || '') + ' ' + String(err.description || '');
  const timedOut = /timed?\s*out|ETIMEDOUT|ESOCKETTIMEDOUT/i.test(msg) || err.code === 'ETIMEDOUT';
  let status = null;
  for (const c of [err.statusCode, err.httpCode, item.statusCode]) {
    const n = typeof c === 'string' ? parseInt(c, 10) : c;
    if (Number.isInteger(n) && n >= 100 && n <= 599) { status = n; break; }
  }
  if (status === null) {
    const m = msg.match(/\b([45][0-9]{2})\b/);
    if (m) status = parseInt(m[1], 10);
  }
  return { failed: true, status, timedOut };
}

function failureCategory(f) {
  if (f.timedOut) return 'timeout';
  if (f.status === 401) return 'authentication';
  if (f.status === 403) return 'authorization';
  if (f.status !== null && f.status >= 500) return 'http_5xx';
  return 'provider_unavailable';
}

function failureConn(provider, connectionKey, base, f, times) {
  const denied = f.status === 401 || f.status === 403;
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: denied ? 'RED' : 'AMBER',
    severity: denied ? 'critical' : 'warning',
    payload: {
      provider,
      connectionKey,
      reachable: false,
      authorizationState: denied ? 'denied' : 'unknown',
      failureCategory: failureCategory(f)
    }
  };
}

function okConn(provider, connectionKey, base, observedAt) {
  return {
    recordType: 'provider_connection',
    idempotencyKey: base + ':conn',
    status: 'GREEN',
    severity: 'none',
    payload: {
      provider,
      connectionKey,
      reachable: true,
      authorizationState: 'ok',
      lastSuccessfulAt: observedAt
    }
  };
}

const dFail = failureOf(daily);
const pFail = failureOf(paths);

if (dFail.failed || pFail.failed) {
  const f = dFail.failed ? dFail : pFail;
  const record = failureConn('vercel', 'web-analytics', config.bucket, f);
  return [{
    json: {
      observedAt: config.observedAt,
      publishedAt: config.publishedAt,
      freshUntil: config.freshUntil,
      records: [record],
      diagnostics: { dailyFailed: dFail.failed, pathsFailed: pFail.failed, status: f.status }
    }
  }];
}

function toInt(v) {
  const n = typeof v === 'string' ? parseInt(v, 10) : v;
  return Number.isInteger(n) && n >= 0 && n <= 1000000000 ? n : null;
}

// --- daily totals ------------------------------------------------------------
const dRows = Array.isArray(daily.rows) ? daily.rows : [];
const row0 = dRows.length > 0 && dRows[0] && typeof dRows[0] === 'object' ? dRows[0] : {};
const visitors = toInt(row0.visitors);
const pageviews = toInt(row0.pageviews);

// --- top routes (sanitize each path; skip, never guess) ----------------------
function cleanPath(raw) {
  if (typeof raw !== 'string') return null;
  let p = raw.split('?')[0].split('#')[0].trim().toLowerCase();
  if (p === '') p = '/';
  if (p.length > 201 || !/^\/[a-z0-9\/._~-]{0,200}$/.test(p)) return null;
  for (const x of ['/admin', '/agent', '/share', '/api', '/_next', '/_vercel']) {
    if (p.startsWith(x)) return null;
  }
  if (p === '/others') return null;
  return p;
}

const topRoutes = [];
const pRows = Array.isArray(paths.rows) ? paths.rows : [];
for (const r of pRows) {
  if (topRoutes.length >= 20) break;
  const o = r && typeof r === 'object' ? r : {};
  const path = cleanPath(o.requestPath !== undefined ? o.requestPath : o.path);
  const views = toInt(o.pageviews !== undefined ? o.pageviews : o.views);
  if (path === null || views === null) continue; // skip, never guess
  topRoutes.push({ path, views });
}

// --- traffic_summary payload (strict allowlist of migration 0005) ------------
const noData = visitors === null && pageviews === null;
const payload = {
  provider: 'vercel',
  periodStart: config.periodStart,
  periodEnd: config.periodEnd,
  timezone: 'UTC',
  boundary: 'web_analytics_day',
  coverage: noData ? 'no_data' : 'full'
};
if (visitors !== null) payload.visitors = visitors;
if (pageviews !== null) payload.pageviews = pageviews;
if (topRoutes.length > 0) payload.topRoutes = topRoutes;

const records = [{
  recordType: 'traffic_summary',
  idempotencyKey: config.bucket,
  status: noData ? 'NO_DATA' : 'GREEN',
  severity: noData ? 'none' : 'info',
  payload
}];
records.push(okConn('vercel', 'web-analytics', config.bucket, config.observedAt));

return [{
  json: {
    observedAt: config.observedAt,
    publishedAt: config.publishedAt,
    freshUntil: config.freshUntil,
    records,
    diagnostics: {
      visitorsPresent: visitors !== null,
      pageviewsPresent: pageviews !== null,
      topRoutesSeen: pRows.length,
      topRoutesKept: topRoutes.length
    }
  }
}];

// CloudIT - Vercel Traffic Collector — Build Records.
// Purpose: wrap the normalized records (produced by the Normalize node)
// in the strict Phase 0 section 7 evidence envelopes and attach the
// shared run timestamps from Load Config.
// Partial-failure rule (omit, never guess): any value that cannot be read
// from the provider response is OMITTED from the batch — absence shows as
// NO_DATA/stale in the portal, never as a wrong number, and can never
// poison the batch (batch acceptance is all-or-nothing).
// Envelope keys are exactly the Phase 0 contract: contractVersion "1.0",
// recordType, idempotencyKey (<=160 chars, opaque, unique per record),
// environmentKey "production", sourceSystem "vercel", observedAt,
// publishedAt, freshUntil, status, severity, correlationKey null, payload.
// Payload keys stay inside the strict allowlist of migration 0005 — any
// extra key rejects the WHOLE batch with unknown_field.

const input = $input.first().json;

const records = (Array.isArray(input.records) ? input.records : []).map((r) => ({
  contractVersion: '1.0',
  recordType: r.recordType,
  idempotencyKey: String(r.idempotencyKey),
  environmentKey: 'production',
  sourceSystem: 'vercel',
  observedAt: input.observedAt,
  publishedAt: input.publishedAt,
  freshUntil: input.freshUntil,
  status: r.status,
  severity: r.severity,
  correlationKey: null,
  payload: r.payload
}));

return [{
  json: {
    records,
    recordCount: records.length,
    publisherKey: 'cavetta-production-n8n'
  }
}];
